import java.util.*;
import java.io.*;

public class Main {
    static char[][] matrixA = new char[12][12];
    static char[][] matrixB = new char[12][12];
    static int sizeN, maxTime;
    static boolean[][][][][] dpVisited = new boolean[70][12][12][12][12];
    static boolean[][][][] canReach = new boolean[12][12][12][12];
    static int[][] timeGrid = new int[12][12];

    static void propagateDP(int tStep, int x, int y, int xRef, int yRef) {
        if (maxTime >= 70 || x < 0 || x >= sizeN || y < 0 || y >= sizeN)
            return;
        if (matrixA[x][y] < '0' || matrixA[x][y] > '9')
            return;
        if (tStep > maxTime + 1)
            return;
        if (dpVisited[tStep][x][y][xRef][yRef])
            return;
        if (timeGrid[x][y] != 0 && tStep > timeGrid[x][y])
            return;
        if (timeGrid[x][y] == tStep && (matrixB[x][y] > '9' || matrixB[x][y] <= '0'))
            return;
        dpVisited[tStep][x][y][xRef][yRef] = true;

        if (tStep < timeGrid[x][y]) {
            propagateDP(tStep + 1, x, y, xRef, yRef);
            propagateDP(tStep + 1, x + 1, y, xRef, yRef);
            propagateDP(tStep + 1, x - 1, y, xRef, yRef);
            propagateDP(tStep + 1, x, y + 1, xRef, yRef);
            propagateDP(tStep + 1, x, y - 1, xRef, yRef);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int t = Integer.parseInt(st.nextToken());
        sizeN = n;
        maxTime = t;

        for (int i = 0; i < n; i++) {
            String lineA = br.readLine();
            for (int j = 0; j < n; j++) {
                matrixA[i][j] = lineA.charAt(j);
            }
        }
        for (int i = 0; i < n; i++) {
            String lineB = br.readLine();
            for (int j = 0; j < n; j++) {
                matrixB[i][j] = lineB.charAt(j);
            }
        }

        List<List<Integer>> graph = new ArrayList<>();
        int[] E = new int[210];
        int[] H = new int[210];
        int[][] C = new int[210][210];
        int[][] pN = new int[11][11];

        for (int i = 0; i < 210; i++) {
            E[i] = 0;
            H[i] = 0;
            Arrays.fill(C[i], 0);
        }
        for (int i = 0; i < 11; i++) {
            Arrays.fill(pN[i], 0);
        }

        int[][][] F = new int[210][210];
        for (int i = 0; i < 210; i++) {
            for (int j = 0; j < 210; j++) {
                F[i][j] = new int[210];
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                timeGrid[i][j] = -1;
            }
        }

        Queue<int[]> q = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (matrixA[i][j] == 'Z') {
                    timeGrid[i][j] = 0;
                    q.offer(new int[]{i, j});
                }
            }
        }

        int[] di = {-1, 0, 1, 0};
        int[] dj = {0, -1, 0, 1};

        while (!q.isEmpty()) {
            int[] p = q.poll();
            int pi = p[0], pj = p[1];
            if (timeGrid[pi][pj] >= t) continue;
            for (int d = 0; d < 4; d++) {
                int ni = pi + di[d], nj = pj + dj[d];
                if (ni >= 0 && ni < n && nj >= 0 && nj < n && matrixA[ni][nj] >= '0' && matrixA[ni][nj] <= '9' && timeGrid[ni][nj] == -1) {
                    timeGrid[ni][nj] = timeGrid[pi][pj] + 1;
                    q.offer(new int[]{ni, nj});
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (timeGrid[i][j] == -1)
                    timeGrid[i][j] = t;
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (matrixA[i][j] >= '0' && matrixA[i][j] <= '9') {
                    propagateDP(0, i, j, i, j);
                }
            }
        }

        List<Integer> startNodes = new ArrayList<>();
        graph.add(startNodes);

        for (int i1 = 0; i1 < n; i1++) {
            for (int j1 = 0; j1 < n; j1++) {
                for (int i2 = 0; i2 < n; i2++) {
                    for (int j2 = 0; j2 < n; j2++) {
                        for (int nt = 0; nt <= t; nt++) {
                            canReach[i1][j1][i2][j2] |= dpVisited[nt][i1][j1][i2][j2];
                        }
                    }
                }
            }
        }

        for (int i1 = 0; i1 < n; i1++) {
            for (int j1 = 0; j1 < n; j1++) {
                if (matrixA[i1][j1] > '0' && matrixA[i1][j1] <= '9') {
                    int k = graph.size();
                    List<Integer> g = new ArrayList<>();
                    graph.add(g);
                    E[k] = matrixA[i1][j1] - '0';

                    for (int i2 = 0; i2 < n; i2++) {
                        for (int j2 = 0; j2 < n; j2++) {
                            if (matrixB[i2][j2] > '0' && matrixB[i2][j2] <= '9') {
                                if (canReach[i2][j2][i1][j1]) {
                                    int _k;
                                    if (pN[i2][j2] == 0) {
                                        List<Integer> _g = new ArrayList<>();
                                        _k = graph.size();
                                        graph.add(_g);
                                        pN[i2][j2] = _k;
                                    } else {
                                        _k = pN[i2][j2];
                                    }
                                    graph.get(k).add(_k);
                                    graph.get(_k).add(k);
                                    C[k][_k] = 10000;
                                    C[_k][k] = 0;
                                }
                            }
                        }
                    }
                }
            }
        }

        for (int i2 = 0; i2 < n; i2++) {
            for (int j2 = 0; j2 < n; j2++) {
                if (matrixB[i2][j2] > '0' && matrixB[i2][j2] <= '9' && pN[i2][j2] > 0) {
                    int _k = pN[i2][j2];
                    graph.get(_k).add(0);
                    C[_k][0] = matrixB[i2][j2] - '0';
                    C[0][_k] = 0;
                }
            }
        }

        boolean done;
        do {
            done = true;
            for (int i = 1; i < graph.size(); i++) {
                while (E[i] > 0) {
                    boolean progressFlag = true;
                    int minH = Integer.MAX_VALUE;
                    for (int neighbor : graph.get(i)) {
                        if (C[i][neighbor] - E[i] > 0 && H[i] == H[neighbor] + 1) {
                            int deltaFlow = Math.min(C[i][neighbor] - E[i], E[i]);
                            F[i][neighbor] += deltaFlow;
                            F[neighbor][i] -= deltaFlow;
                            E[i] -= deltaFlow;
                            E[neighbor] += deltaFlow;
                            progressFlag = false;
                            done = false;
                            if (E[i] == 0) break;
                        }
                        minH = Math.min(minH, H[neighbor]);
                    }
                    if (H[i] != minH + 1 && minH != Integer.MAX_VALUE)
                        H[i] = minH + 1;
                    if (progressFlag) break;
                }
            }
        } while (!done);

        System.out.println(E[0]);
    }
}
